export class Logger {
  constructor(lines = []) {
    this.lines = lines
  }
  info(message) {
    this.lines.push(message)
  }
}

export class RequestId {
  constructor(value) {
    this.value = value
  }
}

export class LoggedInterceptor {
  constructor(logger) {
    this.logger = logger
  }
  intercept(invocation, options) {
    this.logger.info(`${options?.prefix ?? ''}${invocation.methodName}`)
    return invocation.proceed()
  }
}

export function Logged() {
  return () => {}
}
